  "statement": "Examine os mapas.\n\nPropriedades privadas (99 662 481 hectares)\n\nÁreas de proteção ambiental (19 903 841 hectares)\n\nTerras indígenas (115 091 408 hectares)\n\nUnidades de conservação (94 074 236 hectares)\n\n(https://ipam.org.br. Adaptado.)",
