  "difficulty": "Média",
  "statement": "O esquema ilustra de forma resumida o efeito de um gene recessivo pleiotrópico, cujo efeito primário é produzir uma deficiência na enzima fenilalanina hidroxilase. Nota-se no esquema que as enzimas fenilalanina hidroxilase e tirosinase atuam em conversões de algumas substâncias.\n\nProteína ou aminoácido\n\nFenilalanina\n\nFenilalanina\n\nhidroxilase\n\nTirosina\n\nÁcido fenilpirúvico Tirosinase\n\nMelanina\n\nFenilcetonúria\n\nPele pigmentada",
