  "statement": "O tratamento de esgoto é fundamental para se evitar a transmissão de doenças: um litro de esgoto não tratado pode conter até 20 bilhões de seres procariontes, muitos deles patogênicos para o ser humano, como é o caso dos causadores do cólera e da febre tifoide. Em uma análise laboratorial, a água é considerada de boa qualidade se apresentar menos de dez tipos de coliformes e menos de mil procariontes de outros tipos por litro de água.\n\n(Sônia Lopes e Sergio Rosso. Bio, 2013. Adaptado.)\n\nDe acordo com o texto e conhecimentos sobre o tema, os seres patogênicos citados",
