  "detail": "DNA, RNA e expressão gênica",
  "difficulty": "Média",
  "statement": "Nas Américas, há resistência do Plasmodium vivax, uma das espécies causadoras da malária, ao medicamento cloroquina documentada em ensaios clínicos em localidades do Brasil, do Peru, da Colômbia e da Bolívia. No Brasil, há relatos de resistência nos estados do Amazonas e do Acre.\n\n(Marcelo Urbano Ferreira. Parasitologia contemporânea, 2021. Adaptado.)\n\nDe acordo com a teoria moderna da evolução, a explicação para o surgimento de cepas resistentes de Plasmodium é que",
