    "Correta (D). Conforme a resolução: Cálculo da quantidade, em mol, em 0,75 kg e em 1 kg de acefato ($M = 183\\ \\mathrm{g/mol}$): $n_1 = \\frac{750}{183} \\approx 4{,}1\\ \\mathrm{mol}$ e $n_2 = \\frac{1000}{183} \\approx 5{,}4\\ \\mathrm{mol}$. A solução mais diluída é aquela que utiliza a menor quantidade de soluto no maior volume de água ($400\\ \\mathrm{L}$): $\\mathfrak{M} = \\frac{4{,}1\\ \\mathrm{mol}}{400\\ \\mathrm{L}} \\approx 1{,}0 \\times 10^{-2}\\ \\mathrm{mol/L}$.",
