    "Correta (B). Conforme a resolução: A glicina é o aminoácido mais simples (ácido 2-aminoetanoico). Na reação com o íon hipoclorito (CℓO–), o átomo de carbono da glicina sofre oxidação (o hipoclorito atua como forte agente oxidante). No íon hipoclorito (CℓO–), o oxigênio possui Nox -2, de modo que o cloro apresenta Nox +1 (pois +1 - 2 = -1). Ao atuar como oxidante, o cloro sofre redução, transformando-se em íon cloreto (Cℓ–), cujo Nox é -1. Portanto, as lacunas são preenchidas corretamente por: aminoácido; oxidado; 1+ e 1- (Alternativa B).",
