  "statement": "O flúor-18 (18F) é um radioisótopo utilizado em diagnósticos de câncer, com meia-vida igual a 110 minutos, produzido a partir da reação entre núcleos de neônio (20Ne) e o isótopo X, conforme a equação a seguir:\n\nX Ne 20 10\n\n4\n\n2 18 9F\n\nO isótopo X e a porcentagem de 18F que resta após 5,5 horas de sua produção são, respectivamente,",
