  "statement": "Uma pessoa tocou os polos da bateria de um automóvel, que possui uma diferença de potencial de 12 V, com as duas mãos, uma em cada polo. Considerando que, nessa situação, a resistência elétrica entre as mãos da pessoa seja igual a 4,0 kΩ, a corrente elétrica que percorre o corpo da pessoa terá intensidade igual a",
