  "statement": "A FDA, a agência reguladora de medicamentos dos Estados Unidos, acaba de aprovar a venda de um contraceptivo em gel completamente livre de hormônios. Ele foi desenvolvido por um laboratório americano e age de forma aparentemente simples. Esse contraceptivo altera o pH vaginal e impede a movimentação dos espermatozoides até o ovócito que seria fecundado. Esse método atende as mulheres que não se adaptam aos contraceptivos hormonais.\n\n(Mariana Rosário. “Revolução sem hormônios”. Veja, 10.06.2020. Adaptado.)",
