      "id": "b",
      "prompt": "Faça um desenho que represente a interação entre os íons potássio e a água, indicando a geometria correta da molécula de água. Considerando o grau de ionização do HF igual a 6 × 10–2 e log 6 = 0,8, calcule o pH de uma solução de concentração 0,1 mol/L desse ácido.",
      "maxScore": 2,
      "expected": "ou (1 ponto) Foram aceitas: representar somente uma molécula de água e um íon potássio, desde que indicada claramente a interação (íon-dipolo) entre o íon potássio e o elemento oxigênio da molécula de água; ausência da indicação da densidade de carga negativa da molécula de água. Não foram aceitas: ausência do desenho, ainda que a interação tenha sido explicada de forma dissertativa; geometria molecular incorreta da molécula de H2O; ausência da carga ou carga incorreta do íon potássio; representação de algum íon diferente do íon K+; indicação de ligação covalente ou covalente dativa entre o íon potássio e a molécula de H2O (íon K+ e molécula de H2O unidos por uma linha, ou seta, ou par de elétrons compartilhados, utilizando a estrutura de Lewis); unir o íon K+ e a molécula de H2O com uma seta de uma ponta (ligação covalente dativa), ou de duas pontas (estruturas de ressonância), ou duas setas com sentidos opostos (equilíbrio químico); indicação de reação química entre o íon K+ e H2O (ex. K+ + H2O); fórmula incorreta da molécula de H2O (ex. HO2); eventuais contradições. Vestibular 2022 pH = –log[H+] [H+] = M · α = 0,1 · 6 × 10–2 = 6 × 10–3 mol/L pH = –log (6 × 10–3) = –log 6 – log 10–3 = –0,8 + 3 pH = 2,2 (1 ponto) Foi aceita outra forma correta de resolução (raciocínio) para se chegar ao mesmo resultado. Não foram aceitas: resultados incorretos; arredondamentos do resultado; indicação do cálculo sem se chegar ao resultado final.",
