  "statement": "Dois gatos estão brincando num local onde g = 10 m/s2, conforme representado na imagem. O gato 1 se encontra sobre o tampo de uma mesa, a 0,8 m do chão. O gato 2, que está no chão, na mesma vertical Q que passa pelo gato 1, inicia uma corrida, a partir do repouso, com aceleração a2 constante. No mesmo instante, o gato 1 salta horizontalmente para frente, com velocidade horizontal v1 = 1,5 m/s, levando 0,40 s para atingir o chão. Por fim, os dois gatos chegam ao ponto P no mesmo instante. Para a resolução da questão, despreze as dimensões dos gatos.\n\nGato 1\n\nv1 = 1,5 m/s\n\nMesa\n\nGato 2 0,8 m\n\na2\n\nQ d P",
