  "difficulty": "Média",
  "statement": "Texto 1\n\nCada vez mais, empresas e fábricas implantam tecnologias acionadas por algoritmos inteligentes e que trabalham lado a lado das pessoas. Uma das maiores referências de Inteligência Artificial (IA) no mundo, Andrew Ng, prevê que o avanço da Inteligência Artificial tem potencial para adicionar mais de 10 trilhões de dólares na economia global até 2030.\n\nDe fato, os robôs substituirão os humanos em muitos trabalhos, mas o que muitas pessoas não veem é que isso não é necessariamente algo negativo ou para se temer. Uma automação feita com Inteligência Artificial resolve problemas cotidianos mais recorrentes, principalmente, e isso dá a oportunidade para as pessoas focarem em atividades mais estratégicas ou em estudos e especializações, fomentando um ambiente propício para a geração de ideias inspiradoras e criativas, e também o desenvolvimento de modelos de negócios inovadores.\n\nQuando presenciamos a primeira grande Revolução Industrial, com todos aqueles avanços tecnológicos e a substituição de trabalhadores por máquinas, as pessoas já se perguntavam “e agora? Será esse o destino da humanidade?”, um questionamento que, por sinal, perdura até os dias atuais. A resposta para esse questionamento é que sim, esse é o destino da humanidade, e será cada vez mais, pois ressignificar o trabalho é algo essencial para a sociedade e, quando caminhamos para operações que cada vez mais usam Inteligência Artificial, é importante a entendermos e pensarmos como o que ela de fato é: uma aliada.\n\n(Anderson Paulucci. “A inteligência artificial permitirá que os humanos sejam mais humanos”. https://exame.com, 31.07.2021. Adaptado.)\n\nTexto 2\n\nElon Musk, presidente da Tesla, anunciou, durante evento sobre Inteligência Artificial, que a empresa está construindo um robô humanoide e provavelmente terá um protótipo no próximo ano. “Basicamente, a ideia era que esse robô começasse a substituir seres humanos em trabalhos entediantes, repetitivos e perigosos”, disse Musk sobre o novo empreendimento da Tesla. “Você pode falar com ele e dizer ‘por favor, vá até a loja e compre os seguintes mantimentos’. Esse tipo de coisa. Acho que podemos fazer isso”. Musk também brincou que o robô seria amigável.\n\nO executivo defendeu, ainda, que um robô como esse teria um impacto profundo na economia. Ele disse que o trabalho físico seria uma escolha no futuro, e uma renda básica universal seria necessária. Musk está entre os líderes do Vale do Silício que alertam que a tecnologia pode eliminar o emprego de muitas pessoas e que, portanto, alguns humanos precisarão de outra fonte de renda.\n\n(Matt McFarland. “Elon Musk afirma que Tesla apresentará protótipo de robô humanoide em 2022”. www.cnnbrasil.com.br, 20.08.2021. Adaptado.)\n\nTexto 3\n\nInteligência Artificial é um tema polêmico. Em meio ao desenvolvimento de sistemas capazes de assumir tarefas cada vez mais sofisticadas e de melhorar com a prática, surgem diversas dúvidas. Para o pesquisador Álvaro Machado Dias, da Universidade Federal de São Paulo (Unifesp), sem a vantagem de milhões de anos de evolução, sem emoções nem empatia verdadeiras, as máquinas não serão capazes de pensar como nós. “A mente humana é muito mais um ecossistema cognitivo e, quando a gente olha o funcionamento desse ecossistema, vê que muitas funcionalidades estão enraizadas em capacidades adquiridas ao longo da evolução”, explica.\n\nMas o pesquisador vê, sim, outras ameaças no horizonte, associadas à difusão da Inteligência Artificial. “Daqui a 7 ou 10 anos, teremos uma quantidade de algoritmos suficiente para começarmos a sentir o impacto social da automação no mundo”, diz Álvaro. As mudanças acontecem em ritmo mais acelerado do que em revoluções anteriores — e talvez não haja tempo para que grandes parcelas da população aprendam novas profissões. “Talvez tenhamos a proliferação de algoritmos capazes de ocupar o papel de pessoas na esfera produtiva com mais velocidade do que as pessoas conseguem reinventar seus empregos. Se isso for verdade, podemos ter um aumento irreversível de desemprego e desigualdade”, conclui ele.\n\n(“Como a inteligência artificial nos ameaça, segundo este neurocientista”. https://epocanegocios.globo.com, 14.01.2020. Adaptado.)\n\nCom base nos textos apresentados e em seus próprios conhecimentos, escreva um texto dissertativo-argumentativo, empregando a norma-padrão da língua portuguesa, sobre o tema:\n\nOs impactos da inteligência artificial nas relações de trabalho contemporâneas",
